(() => {
  'use strict';
  const C = 6, R = 12, CELL = 42, TOP = 66, LX = 105, RX = 603, STORE = 'cho-family-bubble-battle-v1';
  const TYPES = ['son', 'second', 'first', 'wife', 'dad'];
  const NAMES = { son: '末っ子', second: '次女', first: '長女', wife: 'お母さん', dad: 'お父さん' };
  const COLORS = ['#72d957', '#ff73ae', '#5fbaff', '#ffd14a', '#508cf4'];
  const crops = { son:[627,627,627,627,'family'], second:[0,627,627,627,'family'], first:[627,0,627,627,'family'], wife:[0,0,627,627,'family'], dad:[0,0,1254,1254,'dad'] };
  const images = { family:new Image(), dad:new Image() }; images.family.src='./assets/family-characters.png'; images.dad.src='./assets/dad-character.png';
  const canvas = document.getElementById('battleCanvas'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id), el = { app:$('battleApp'), start:$('battleStartModal'), result:$('battleResultModal'), startButton:$('battleStartButton'), retry:$('battleRetryButton'), change:$('battleChangeButton'), fresh:$('battleNewGameButton'), msg:$('battleMessage'), board:$('battleLeaderboard'), leftName:$('battleLeftName'), rightName:$('battleRightName'), leftChain:$('battleLeftChain'), rightChain:$('battleRightChain'), timer:$('battleTimer'), title:$('battleResultTitle'), text:$('battleResultText') };
  let visible=false, playing=false, leftLeader='son', rightLeader='dad', grids, pieces, nextDrop=0, started=0, last=performance.now(), elapsed=0, chains=[0,0], maxChains=[0,0], winner=-1;
  const blank = () => Array.from({length:R},()=>Array(C).fill(null));
  const rand = () => Math.floor(Math.random()*TYPES.length);
  const format = ms => `${String(Math.floor(ms/60000)).padStart(2,'0')}:${String(Math.floor(ms%60000/1000)).padStart(2,'0')}`;
  const cellX = p => (p?RX:LX), inside = (g,x,y) => x>=0&&x<C&&y<R&&(!g[y]||g[y][x]===null);
  function freshPiece() { return { x:2, y:-1, a:rand(), b:rand(), rot:0 }; }
  function positions(p) { const d=[[0,-1],[1,0],[0,1],[-1,0]][p.rot]; return [[p.x,p.y,p.a],[p.x+d[0],p.y+d[1],p.b]]; }
  function legal(side,p) { return positions(p).every(([x,y])=>y<0 || inside(grids[side],x,y)); }
  function move(side,dx,dy) { const p={...pieces[side],x:pieces[side].x+dx,y:pieces[side].y+dy}; if(!legal(side,p)) return false; pieces[side]=p; return true; }
  function rotate(side) { const p={...pieces[side],rot:(pieces[side].rot+1)%4}; if(legal(side,p)) pieces[side]=p; }
  function lock(side) { const g=grids[side]; let dead=false; positions(pieces[side]).forEach(([x,y,t])=>{ if(y<0) dead=true; else g[y][x]=t; }); if(dead) return end(1-side); chains[side]=clearChains(side); maxChains[side]=Math.max(maxChains[side],chains[side]); if(chains[side]>1) sendGarbage(1-side, Math.min(6,chains[side]-1)); pieces[side]=freshPiece(); if(!legal(side,pieces[side])) end(1-side); updateHud(); }
  function clearChains(side) { const g=grids[side]; let chain=0, changed=true; while(changed){ changed=false; const seen=Array.from({length:R},()=>Array(C).fill(false)), gone=[]; for(let y=0;y<R;y++)for(let x=0;x<C;x++){ if(g[y][x]===null||g[y][x]===-1||seen[y][x])continue; const group=[], q=[[x,y]];seen[y][x]=true;while(q.length){const[a,b]=q.pop();group.push([a,b]);[[1,0],[-1,0],[0,1],[0,-1]].forEach(([dx,dy])=>{const nx=a+dx,ny=b+dy;if(nx>=0&&nx<C&&ny>=0&&ny<R&&!seen[ny][nx]&&g[ny][nx]===g[y][x]){seen[ny][nx]=true;q.push([nx,ny]);}})}if(group.length>=4)gone.push(...group); } if(gone.length){changed=true;chain++;gone.forEach(([x,y])=>g[y][x]=null);gravity(g);} } return chain; }
  function gravity(g){for(let x=0;x<C;x++){let write=R-1;for(let y=R-1;y>=0;y--)if(g[y][x]!==null){g[write][x]=g[y][x];if(write!==y)g[y][x]=null;write--;}for(;write>=0;write--)g[write][x]=null;}}
  function sendGarbage(side,n){const g=grids[side];for(let i=0;i<n;i++){const x=Math.floor(Math.random()*C);let y=R-1;while(y>=0&&g[y][x]!==null)y--;if(y<0){end(1-side);return;}g[y][x]=-1;}}
  function drop(side){if(!move(side,0,1))lock(side);}
  function updateHud(){el.leftChain.textContent=`${maxChains[0]} れんさ`;el.rightChain.textContent=`${maxChains[1]} れんさ`;}
  function load(){try{return JSON.parse(localStorage.getItem(STORE)||'{}')}catch{return{}}}
  function renderRecords(){const data=load(), rows=Object.entries(data).sort((a,b)=>b[1].wins-a[1].wins||b[1].bestChain-a[1].bestChain).slice(0,7);el.board.replaceChildren();if(!rows.length){const li=document.createElement('li');li.className='empty';li.textContent='まだ きろくが ありません';el.board.append(li);return;}rows.forEach(([key,r])=>{const li=document.createElement('li'),n=document.createElement('span'),p=document.createElement('span');n.className='name';p.className='points';n.textContent=NAMES[key];p.textContent=`${r.wins}勝`;const s=document.createElement('small');s.textContent=`最高 ${r.bestChain}れんさ`;p.append(s);li.append(n,p);el.board.append(li);});}
  function end(side){if(!playing)return;playing=false;winner=side;const key=side?rightLeader:leftLeader,data=load(),r=data[key]||{wins:0,bestChain:0,bestTime:null};r.wins++;r.bestChain=Math.max(r.bestChain,maxChains[side]);r.bestTime=r.bestTime===null?elapsed:Math.min(r.bestTime,elapsed);data[key]=r;localStorage.setItem(STORE,JSON.stringify(data));renderRecords();el.title.textContent=`${side?'プレイヤー 2':'プレイヤー 1'} の勝ち！`;el.text.textContent=`${NAMES[key]}の最高れんさ ${maxChains[side]}！　${format(elapsed)}`;setTimeout(()=>el.result.classList.add('visible'),500);}
  function start(){leftLeader=document.querySelector('input[name="battleLeft"]:checked').value;rightLeader=document.querySelector('input[name="battleRight"]:checked').value;grids=[blank(),blank()];pieces=[freshPiece(),freshPiece()];maxChains=[0,0];chains=[0,0];started=performance.now();elapsed=0;nextDrop=started+650;playing=true;el.start.classList.remove('visible');el.result.classList.remove('visible');el.leftName.textContent=`P1 ${NAMES[leftLeader]}`;el.rightName.textContent=`P2 ${NAMES[rightLeader]}`;updateHud();}
  function drawBubble(x,y,t,size=CELL-4){ctx.save();ctx.translate(x,y);ctx.fillStyle=t===-1?'#a5afbc':COLORS[t];ctx.beginPath();ctx.arc(0,0,size/2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba(255,255,255,.7)';ctx.lineWidth=2;ctx.stroke();if(t>=0){const key=TYPES[t],crop=crops[key],img=images[crop[4]];if(img.complete){ctx.beginPath();ctx.arc(0,0,size*.34,0,Math.PI*2);ctx.clip();ctx.drawImage(img,crop[0],crop[1],crop[2],crop[3],-size*.34,-size*.34,size*.68,size*.68);}}ctx.restore();}
  function drawField(side){const x0=cellX(side),g=grids?.[side];ctx.fillStyle=side?'#15294a':'#26315a';ctx.fillRect(x0-8,TOP-8,C*CELL+16,R*CELL+16);ctx.fillStyle='#071326';ctx.fillRect(x0,TOP,C*CELL,R*CELL);for(let y=0;y<R;y++)for(let x=0;x<C;x++){ctx.strokeStyle='rgba(255,255,255,.08)';ctx.strokeRect(x0+x*CELL,TOP+y*CELL,CELL,CELL);if(g && g[y][x] !== null)drawBubble(x0+x*CELL+CELL/2,TOP+y*CELL+CELL/2,g[y][x]);}ctx.strokeStyle='#ff8aa9';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x0,TOP+CELL);ctx.lineTo(x0+C*CELL,TOP+CELL);ctx.stroke();if(pieces?.[side])positions(pieces[side]).forEach(([x,y,t])=>{if(y>=0)drawBubble(x0+x*CELL+CELL/2,TOP+y*CELL+CELL/2,t);});}
  function draw(){ctx.fillStyle='#08182f';ctx.fillRect(0,0,960,600);ctx.fillStyle='#fff';ctx.font='900 24px sans-serif';ctx.textAlign='center';ctx.fillText('P1  W A S D',230,37);ctx.fillText('P2  ↑ ← ↓ →',730,37);drawField(0);drawField(1);ctx.fillStyle='#ffcc42';ctx.font='950 34px sans-serif';ctx.fillText('VS',480,310);}
  function gameTick(){if(!visible||!playing)return;const now=performance.now();elapsed=now-started;el.timer.textContent=format(elapsed);if(now>=nextDrop){drop(0);drop(1);nextDrop=now+Math.max(210,650-Math.floor(elapsed/20000)*65);}}
  function frame(){if(visible)draw();requestAnimationFrame(frame);}
  function key(e){if(!visible||!playing)return;const pressed=e.key.length===1?e.key.toLowerCase():e.key;const map={a:[0,-1,0],d:[0,1,0],s:[0,0,1],w:[0,0,0],ArrowLeft:[1,-1,0],ArrowRight:[1,1,0],ArrowDown:[1,0,1],ArrowUp:[1,0,0]};const m=map[pressed];if(!m)return;e.preventDefault();if(pressed==='w'||pressed==='ArrowUp')rotate(m[0]);else if(m[2]){while(move(m[0],0,1));lock(m[0]);}else move(m[0],m[1],0);}
  window.addEventListener('keydown',key);el.startButton.addEventListener('click',start);el.retry.addEventListener('click',start);el.change.addEventListener('click',()=>{el.result.classList.remove('visible');el.start.classList.add('visible');});el.fresh.addEventListener('click',()=>{playing=false;el.start.classList.add('visible');});
  function open(){visible=true;renderRecords();el.start.classList.add('visible');}function leave(){visible=false;playing=false;el.start.classList.remove('visible');el.result.classList.remove('visible');}setInterval(gameTick,40);requestAnimationFrame(frame);window.FamilyBubbleBattle={open,leave};
})();
